    explanation: 'OA機器等の「その他」は建築設備側で制御できないため、設計値・基準値に同じ値を用い、適合判定の削減対象とならない。建築物省エネ法の一次エネルギー消費量計算では、空調・換気・照明・給湯・昇降機の5設備が設計者の工夫で削減できる評価対象となる。OA機器やコンセント負荷などの「その他一次エネルギー消費量」は設計値と基準値に同じ値を用いるため、BEIの分子分母に同額が加わり削減対象にはならない。\n\n【図解】一次エネルギー消費量の区分\n　区分｜対象設備｜評価上の扱い\n　適合判定の対象｜空調・換気・照明・給湯・昇降機｜設計値と基準値を比較\n　その他｜OA機器・コンセント負荷等｜設計値＝基準値の定数\n　太陽光発電等｜創エネルギー｜設計値から差し引く\n　⇒ BEIは設計一次エネ消費量を基準一次エネ消費量で除した値\n　⚠ その他消費量を削減対象と考えるのは誤り。分母分子に同じ値が入る。',
