    correctKey: 'D',
    explanation: 'CO2放出後の入室は死亡事故につながる。排出装置による消火剤の排出、濃度確認後に入室する。保守点検時の閉止弁の運用も重要。二酸化炭素消火設備は放出後の区画内が酸欠状態となるため、消火確認後は排出装置や換気設備で消火剤を屋外へ排出し、酸素濃度が安全であることを確認してから入室する。保守点検時には起動用ガス容器や選択弁の閉止弁を確実に閉止し、誤放出を防止する運用が求められる。\n\n【図解】二酸化炭素消火設備の運用手順\n　段階｜動作｜安全上の要点\n　起動｜音響警報の発報｜在室者の退避を促す\n　遅延｜20秒以上の遅延｜退避完了までの時間確保\n　放出後｜排出装置による排出と換気｜濃度確認後に入室\n　⇒ 放出直後の入室は死亡事故に直結する\n　⚠ 「消火後はただちに入室してよい」は誤り。排出と濃度確認が必須。',
